-- Customer Shopping Behavior Analysis
-- MySQL 8+

CREATE DATABASE IF NOT EXISTS customer_behavior;
USE customer_behavior;

-- Basic validation after importing clean_data.csv
SHOW TABLES;
DESCRIBE clean_data;

SELECT COUNT(*) AS total_records
FROM clean_data;

SELECT COUNT(*) AS total_columns
FROM information_schema.columns
WHERE table_schema = 'customer_behavior'
  AND table_name = 'clean_data';

SELECT *
FROM clean_data
LIMIT 5;

-- Q1. What is the total revenue generated by male vs. female customers?
SELECT
    gender,
    SUM(purchase_amount) AS total_revenue
FROM clean_data
GROUP BY gender
ORDER BY total_revenue DESC;

-- Q2. Which customers used a discount but still spent more than the average purchase amount?
SELECT
    customer_id,
    purchase_amount
FROM clean_data
WHERE discount_applied = 'Yes'
  AND purchase_amount > (SELECT AVG(purchase_amount) FROM clean_data)
ORDER BY purchase_amount DESC;

-- Q3. Which five products have the highest average review rating?
SELECT
    item_purchased,
    ROUND(AVG(review_rating), 2) AS average_product_rating
FROM clean_data
GROUP BY item_purchased
ORDER BY average_product_rating DESC
LIMIT 5;

-- Q4. Compare average purchase amounts for Standard and Express shipping.
SELECT
    shipping_type,
    ROUND(AVG(purchase_amount), 2) AS average_purchase_amount
FROM clean_data
WHERE shipping_type IN ('Standard', 'Express')
GROUP BY shipping_type
ORDER BY average_purchase_amount DESC;

-- Q5. Do subscribed customers spend more?
SELECT
    subscription_status,
    COUNT(customer_id) AS total_customers,
    ROUND(AVG(purchase_amount), 2) AS average_spend,
    ROUND(SUM(purchase_amount), 2) AS total_revenue
FROM clean_data
GROUP BY subscription_status
ORDER BY total_revenue DESC;

-- Q6. Which five products have the highest percentage of discounted purchases?
SELECT
    item_purchased,
    ROUND(
        100.0 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END) / COUNT(*),
        2
    ) AS discount_rate_pct
FROM clean_data
GROUP BY item_purchased
ORDER BY discount_rate_pct DESC
LIMIT 5;

-- Q7. Segment customers based on their number of previous purchases.
WITH customer_segments AS (
    SELECT
        customer_id,
        CASE
            WHEN previous_purchases = 1 THEN 'New'
            WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
            ELSE 'Loyal'
        END AS customer_segment
    FROM clean_data
)
SELECT
    customer_segment,
    COUNT(*) AS number_of_customers
FROM customer_segments
GROUP BY customer_segment
ORDER BY number_of_customers DESC;

-- Q8. What are the three most-purchased products within each category?
WITH item_counts AS (
    SELECT
        category,
        item_purchased,
        COUNT(*) AS total_orders
    FROM clean_data
    GROUP BY category, item_purchased
),
ranked_items AS (
    SELECT
        category,
        item_purchased,
        total_orders,
        ROW_NUMBER() OVER (
            PARTITION BY category
            ORDER BY total_orders DESC, item_purchased
        ) AS item_rank
    FROM item_counts
)
SELECT
    item_rank,
    category,
    item_purchased,
    total_orders
FROM ranked_items
WHERE item_rank <= 3
ORDER BY category, item_rank;

-- Q9. Are repeat buyers (more than five previous purchases) more likely to subscribe?
-- Comparing rates avoids a misleading conclusion based only on group counts.
WITH buyer_groups AS (
    SELECT
        CASE
            WHEN previous_purchases > 5 THEN 'Repeat buyer'
            ELSE 'Five or fewer previous purchases'
        END AS buyer_group,
        subscription_status
    FROM clean_data
)
SELECT
    buyer_group,
    COUNT(*) AS total_customers,
    SUM(CASE WHEN subscription_status = 'Yes' THEN 1 ELSE 0 END) AS subscribers,
    ROUND(
        100.0 * SUM(CASE WHEN subscription_status = 'Yes' THEN 1 ELSE 0 END) / COUNT(*),
        2
    ) AS subscription_rate_pct
FROM buyer_groups
GROUP BY buyer_group
ORDER BY subscription_rate_pct DESC;

-- Q10. What is the revenue contribution of each age group?
SELECT
    age_group,
    SUM(purchase_amount) AS total_revenue
FROM clean_data
GROUP BY age_group
ORDER BY total_revenue DESC;
